head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil11040";
scwin.result = null;
scwin.attachedNum = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil11040.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isDisclsConsultServiced", fn: function () { return String(String((dma_pageContext.get("isDisclsConsultServiced") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getAttachFileList();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name attachFileList_oncellclick
 * @description attachFileList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'attachFileNm') { const d = $c.util.getComponent('dlt_attachFileList'); if (!d) { return; } await scwin.fileDown(String(d.getCellData(rowIndex, "disclsConsultApplId")), String(d.getCellData(rowIndex, "seq"))); return; }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.attachFileList_oncellclick' }); }
};

/**
 * @method
 * @name disclsConsultForm_onsubmit
 * @description disclsConsultForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.disclsConsultForm_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11040.disclsConsultForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_list_onclick = async function(e){
    try {
        await scwin.list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.btn_list_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_list
 * @description list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_list = async function () {
    const sbmOptions = {
        id: "tx_fn_list",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_listReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_getAttachFileList
 * @description get Attach File List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_getAttachFileList = async function () {
    const sbmOptions = {
        id: "tx_fn_getAttachFileList",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_getAttachFileListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_getOtherData
 * @description get Other Data 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_getOtherData = async function () {
    const sbmOptions = {
        id: "tx_fn_getOtherData",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_getOtherDataReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_fileDown
 * @description file Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/status/disclsConsult.do", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name attachFileList_fmt_attachFileNm
 * @description attach File List fmt attach File Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.attachFileList_fmt_attachFileNm = function (data, formattedData, rowIndex, columnIndex) { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; };

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $("input[name='method']").val("disclsConsultApplList");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do") */
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    const nr = await scwin.tx_fn_list();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil11000/jldfil11000.xml", { "method": "disclsConsultApplList" });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} ipt_disclsConsultApplId ipt_disclsConsultApplId
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (ipt_disclsConsultApplId, seq) {
    const isDisclsConsultServiced = $c.util.getComponent('ipt_isDisclsConsultServiced').getValue();
    if (isDisclsConsultServiced === 'Y') {
        const oData = await scwin.getOtherData();
        if (oData === '' || oData === null || oData === 'undefined') {
            void('apiKey 조회에 실패');
            return;
        }
        const arr = oData.split('||');
        const apiUrl = scwin.urlInfo();
        $c.util.getComponent('hideFrame').src = apiUrl + '/auth/s1/disclosure/consult-apply/file-download/' + ipt_disclsConsultApplId + '/' + seq + '?apiKey=' + arr[0] + '&integUsrId=' + arr[1];
    } else {
        (document.fileDownForm || { elements: [] }).target = "hideFrame";
        $c.util.getComponent('dma_listReq').set('method', 'disclsConsultFileDown');
        $c.util.getComponent('dma_listReq').set('disclsConsultApplId', ipt_disclsConsultApplId);
        $c.util.getComponent('dma_listReq').set('seq', seq);
        $c.util.getComponent('dma_listReq').set('apiKey', '');
        $c.util.getComponent('dma_listReq').set('integUsrId', '');
        (document.fileDownForm || { elements: [] }).action = 'disclsConsult.do';
        await scwin.tx_fn_fileDown();
    }
};

/**
 * @method
 * @name urlInfo
 * @description url Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.urlInfo = function () {
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getAttachFileListDone
 * @description get Attach File List Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getAttachFileListDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data); $c.util.getComponent('dlt_attachFileList').setJSON(scwin.result);
    if (scwin.result.length > 0) {
        /* 컨테이너 비움 → setJSON 전체 교체가 대신(D14-A) */
        scwin.attachedNum = scwin.result.length;
        const dCnt = 1;
        /* 컨테이너 조립 루프 → 그리드 공급으로 대체(D14-A): 행은 dlt_attachFileList 가 싣고 열 동작은 그리드 라우터가 낸다 */
        $c.util.getComponent('attachFileList').setStyle("display", "");
    }
};

/**
 * @method
 * @name getAttachFileList
 * @description get Attach File List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getAttachFileList = async function () {
    const r = await scwin.tx_fn_getAttachFileList();
    try {
        scwin.getAttachFileListDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil11040.fn_getAttachFileList' });
    }
    return r;
};

/**
 * @method
 * @name getOtherDataDone
 * @description get Other Data Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getOtherDataDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    otherData = scwin.result.apiKey + '||' + scwin.result.integUsrId;
};

/**
 * @method
 * @name getOtherData
 * @description get Other Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getOtherData = async function () {
    const r = await scwin.tx_fn_getOtherData();
    try {
        scwin.getOtherDataDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil11040.fn_getOtherData' });
    }
    return r;
};
